process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { for i in 1 2 3; do s=$(printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 10 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2); [ "$s" = 502 ] || break; sleep 2; done; echo "$s"; }
serve() { echo "MAPPED_$1" | timeout 120 nc -l -p "$1" > /tmp/r; echo "RECEIVED_$2=$(cat /tmp/r)"; }
echo ALLOWED=$(p 1.1.1.1:443)
echo RELAY_PROXY=$(p 10.231.0.2:8082)
nc -z -w 3 10.231.1.254 8082 && echo RELAY_DIRECT=REACHED || echo RELAY_DIRECT=BLOCKED
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
serve 8082 1
serve 8083 2
